package cli

import (
	"github.com/spf13/cobra"
)

func newFlightsCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "flights",
		Short:       "Search flight locations and travel policy preferences",
		Annotations: map[string]string{"mcp:read-only": "true", "pp:parent-group": "true", "pp:api-resource": "true"},
		RunE:        parentNoSubcommandRunE(flags),
	}

	cmd.AddCommand(newFlightsLocationsCmd(flags))
	cmd.AddCommand(newFlightsPreferencesCmd(flags))
	cmd.AddCommand(newFlightsSearchCmd(flags))
	return cmd
}
